<?php
/**
 * Plugin Name: NESports Auto Updater V16
 * Description: Eliminates card inside card, sets 100% genuine crimson red belt and gear, updates authentic model shots.
 * Version: 16.0.0
 * Author: NESports
 */

function run_nesports_master_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store'
    );
    
    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'templates/sections/section-categories.php' => base64_decode(''),
        'templates/sections/section-bundles.php' => base64_decode(''),
        'templates/sections/section-clothing.php' => base64_decode(''),
        'templates/sections/section-color.php' => base64_decode(''),
        'assets/css/nesports-frontend.css' => base64_decode(''),
        'assets/images/model-lifting-straps-red.jpg' => base64_decode(''),
        'assets/images/straps-red-angle-800x800.jpg' => base64_decode(''),
        'assets/images/belt-crimson-red-800x800.jpg' => base64_decode(''),
        'assets/images/belt-crimson-red-flat-800x800.jpg' => base64_decode(''),
        'assets/images/belt-crimson-red-model-800x800.jpg' => base64_decode(''),
        'assets/images/clothing/norm-lift-the-world-red.jpg' => base64_decode(''),
        'assets/images/clothing/norm-lift-the-world-red-front.jpg' => base64_decode(''),
        'assets/images/clothing/model-lift-the-world-red-sq.jpg' => base64_decode(''),
        'assets/images/clothing/model-strength-club-back.jpg' => base64_decode(''),
        'assets/images/clothing/model-lift-the-world-back.jpg' => base64_decode(''),
        'assets/images/clothing/model-anime-back.jpg' => base64_decode(''),
        'assets/images/clothing/model-son-of-the-west-back.jpg' => base64_decode(''),
        'assets/images/clothing/model-pro-coach-back.jpg' => base64_decode(''),
        'assets/images/clothing/hoodie-pro-coach-back.jpg' => base64_decode(''),
        'assets/images/clothing/hoodie-pro-coach-front.jpg' => base64_decode(''),
        'assets/images/clothing/trousers-lifter-sweatpants.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-green.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-green-front.jpg' => base64_decode(''),
        'assets/images/clothing/model-pro-coach-green-sq.jpg' => base64_decode(''),
        'assets/images/clothing/norm-lift-the-world-black.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-black.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-black-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-blue.jpg' => base64_decode(''),
        'assets/images/clothing/norm-strength-club-blue-front.jpg' => base64_decode(''),
        'assets/images/clothing/norm-pro-coach-navy.jpg' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                wp_mkdir_p($d);
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_update']) && $_GET['nesports_apply_update'] === '1') {
        $res = run_nesports_master_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_master_update();
});
